setInterval(updateWakesToday, 30000);
updateWakesToday();
setInterval(updateTimeUntilNextWake, 30000);
updateTimeUntilNextWake();
setInterval(updateTotalWakes, 30000);
updateTotalWakes();
setInterval(updateDaysActive, 30000);
